RAILS_ENV=test bundle exec ruby -r ./spec/rails_helper -e '
def trace_fab(label)
  queries = []
  sub = ActiveSupport::Notifications.subscribe("sql.active_record") do |*, payload|
    next if payload[:name] == "SCHEMA"
    queries << [payload[:name], payload[:sql]]
  end
  t0 = Process.clock_gettime(Process::CLOCK_MONOTONIC)
  obj = nil
  ActiveRecord::Base.transaction do
    obj = yield
    raise ActiveRecord::Rollback
  end
  elapsed = (Process.clock_gettime(Process::CLOCK_MONOTONIC) - t0) * 1000
  ActiveSupport::Notifications.unsubscribe(sub)
  puts "=== #{label}: #{queries.size} queries, #{elapsed.round(2)}ms ==="
  queries.each_with_index { |(name, sql), i| puts "  #{i+1}. [#{name}] #{sql[0, 140]}" }
end

# warmup
ActiveRecord::Base.transaction { Fabricate(:status); raise ActiveRecord::Rollback }

trace_fab("Fabricate(:account)") { Fabricate(:account) }
trace_fab("Fabricate(:remote_account)") { Fabricate(:remote_account) }
trace_fab("Fabricate(:user)") { Fabricate(:user) }
trace_fab("Fabricate(:admin_user)") { Fabricate(:admin_user) }
trace_fab("Fabricate(:status)") { Fabricate(:status) }
'

